from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
UP=ROOT/'plaits/upstream'
REF=Path(r'C:\Proj SSD\CODEX\CIRCUITS-HACKS-RC-main\CIRCUITS-HACKS-RC-main')
OUT=ROOT/'builds/phase20e-full-plaits-audit'
inventory=json.loads((OUT/'source-inventory.json').read_text())
reclaim=json.loads((OUT/'reclaim.json').read_text())
host={int(r['index']):r for r in csv.DictReader((OUT/'host-probe.csv').open(encoding='utf-8-sig'))}
def cite(path, symbol=None, reference=False):
    p=(REF if reference else UP)/path
    lines=p.read_text(encoding='utf-8').splitlines()
    line=next((i for i,s in enumerate(lines,1) if symbol and symbol in s),1)
    return f'[{path}'+(f' — {symbol}' if symbol else '')+f'](<{p.as_posix()}:{line}>)'
def local(path): return f'[{path}](<{(ROOT/path).as_posix()}>)'
def c(path,symbol=None):return cite(path,symbol,True)
